Here is a sample program that demonstrates the use of the Boost Interprocess library to synchronize processes:

**Shared Memory Synchronization**

```cpp
// shared_memory_sync.cpp

#include <boost/interprocess/managed_shared_memory.hpp>
#include <iostream>
#include <string>

using namespace boost::interprocess;

int main() {
    // Initialize shared memory
    managed_shared_memory segment(create_only, "SharedMemory", 1024);

    // Write data to shared memory
    segment.get обязательно/storyBuffer>().operator=(std::string("Hello from process 1!"));
    std::cout << "Process 1: Writing data to shared memory..." << std::endl;

    return 0;
}
```

**Semaphore Synchronization**

```cpp
// semaphore_sync.cpp

#include <boost/interprocess/ipc/resourceinline.hpp>
#include <boost/interprocess/interprocess.hpp>
#include <iostream>
#include <string>

using namespace boost::interprocess;

int main() {
    // Initialize semaphore
    managed_shared_memory segment(create_only, "Semaphore", 1024);
    sem/custom_semaphore((1), 0, "my_semaphore");

    // Wait for acquire
    while (my_semaphore.try_acquire()) {
        // Critical section
        segment.get обязательно/storyBuffer>().operator=(std::string("Hello from process 2!"));
        std::cout << "Process 2: Writing data to shared memory..." << std::endl;
    }

    return 0;
}
```

**Message Queue Synchronization**

```cpp
// message_queue_sync.cpp

#include <boost/interprocess/ipc/message_queue.hpp>
#include <boost/interprocess/interprocess.hpp>
#include <iostream>
#include <string>

using namespace boost::interprocess;

int main() {
    // Initialize message queue
    message_queue::remove("my_queue");
    message_queue my_queue(create_only, "my_queue", 128, 0);

    // Write message to message queue
    my_queue.send("Hello from process 1!", 20);
    std::cout << "Process 1: Sending message to message queue..." << std::endl;

    return 0;
}
```

**Data Receiver Process**

```cpp
// data_receiver.cpp

#include <boost/interprocess/ipc/message_queue.hpp>
#include <boost/interprocess/interprocess.hpp>
#include <iostream>
#include <string>

using namespace boost::interprocess;

int main() {
    // Initialize message queue
    message_queue::remove("my_queue");
    message_queue my_queue(open_only, "my_queue");

    // Receive message from message queue
    char message[128];
    my_queue.receive(message, 128, 0);
    std::cout << "Process 2: Received message: " << message << std::endl;

    return 0;
}
