// функция для вычисления интеграла методом прямоугольников
double integrateRectangle(int numPoints, double lowerBound, double upperBound, double (*func)(double)) {
    double h = (upperBound - lowerBound) / numPoints;
    double sum = 0;
    for (int i = 0; i < numPoints; i++) {
        sum += func(lowerBound + i * h);
    }
    return sum * h;
}

// функция для вычисления интеграла методом трапеций
double integrateTrapezoid(int numPoints, double lowerBound, double upperBound, double (*func)(double)) {
    double h = (upperBound - lowerBound) / numPoints;
    double sum = 0;
    for (int i = 0; i < numPoints; i++) {
        if (i == 0) {
            sum += func(lowerBound);
        } else if (i == numPoints - 1) {
            sum += func(upperBound);
        } else {
            sum += func(lowerBound + i * h);
        }
    }
    return (h / 2) * sum;
}

// функция для вычисления интеграла методом Симпсона
double integrateSimpson(int numPoints, double lowerBound, double upperBound, double (*func)(double)) {
    double h = (upperBound - lowerBound) / numPoints;
    double sum = 0;
    for (int i = 0; i < numPoints; i++) {
        if (i == 0 || i == numPoints - 1) {
            sum += func(lowerBound + i * h);
        } else if (i % 2 == 0) {
            sum += 2 * func(lowerBound + i * h);
        } else {
            sum += 4 * func(lowerBound + i * h);
        }
    }
    return (h / 3) * sum;
}

