    struct {
        int method;
        int numPoints;
        double lowerBound;
        double upperBound;
        double (*func)(double);
        CRITICAL_SECTION *mutex;
    } *params = (struct {}) *lpParam;

    double result = 0;

    switch (params->method) {
    case 0:
        result = integrateRectangle(params->numPoints, params->lowerBound, params->upperBound, params->func);
        break;
    case 1:
        result = integrateTrapezoid(params->numPoints, params->lowerBound, params->upperBound, params->func);
        break;
    case 2:
        result = integrateSimpson(params->numPoints, params->lowerBound, params->upperBound, params->func);
        break;
    }

    EnterCriticalSection(params->mutex);
    ::OutputDebugStringA(reinterpret_cast<char*>(params->method));
    ::OutputDebugStringA(" ");
    DoubleToLString(result);
    ::OutputDebugStringA("\r\n");
    LeaveCriticalSection(params->mutex);

    return 0;
}

int main() {
