    const int numPoints = 1000; // количество точек для интегрирования
    const double lowerBound = 0; // нижняя граница интегрирования
    const double upperBound = 1; // верхняя граница интегрирования
    const double (*func)(double) = [](double x) { return x * x; }; // функция для интегрирования

    HANDLE threads[numThreads]; // массив handle потоков
    CRITICAL_SECTION mutex; // мьютекс для синхронизации вывода
    CreateMutex(&mutex, FALSE, NULL);

    for (int i = 0; i < numThreads; i++) {
        struct {
            int method;
            int numPoints;
            double lowerBound;
            double upperBound;
            double (*func)(double);
            CRITICAL_SECTION *mutex;
        } params = {i % 3, numPoints, lowerBound, upperBound, func, &mutex};
        CreateSemaphore(NULL, 0, 1, NULL); // создаем семафор, который начинается в 0
        threads[i] = CreateThread(NULL, 0, threadFunc, &params, 0, NULL);
        Sleep(100); // SMALL RANDOM DELAY
    }

    WaitForMultipleObjects(numThreads, threads, TRUE, INFINITE);

    CloseHandle(mutex);

    return 0;
}
