//Represenación del nodo del árbol binario
struct Node {
    int valor;
    Node* izquierda;
    Node* derecha;
};

//Funión para crear un nodo del árbol binario
Node* crearNodo(int valor) {
    Node* nodo = new Node();
    nodo->valor = valor;
    nodo->izquierda = nullptr;
    nodo->derecha = nullptr;
    return nodo;
}

//Algoritmo de búsqueda en un árbol binario
bool buscar(Node* nodo, int valorBuscado) {
    if (nodo == nullptr) {
        return false; //No se encontró el valor
    }

    if (nodo->valor == valorBuscado) {
        return true; //Encontró el valor
    }

    if (nodo->valor < valorBuscado) {
        return buscar(nodo->derecha, valorBuscado); //Buscar en la rama derecha
    } else {
        return buscar(nodo->izquierda, valorBuscado); //Buscar en la rama izquierda
    }
}

//Ejemplo de uso
