    Node* raiz = crearNodo(5);
    raiz->izquierda = crearNodo(3);
    raiz->derecha = crearNodo(7);
    raiz->izquierda->izquierda = crearNodo(2);
    raiz->izquierda->derecha = crearNodo(4);
    raiz->derecha->izquierda = crearNodo(6);
    raiz->derecha->derecha = crearNodo(8);

