    [2, 4, 6]
  ];

  for (let combination of winningCombinations) {
    if (
      board[combination[0]] &&
      board[combination[0]] === board[combination[1]] &&
      board[combination[0]] === board[combination[2]]
    ) {
      return board[combination[0]];
    }
  }

  return null;
}

// Function to check if the game is a draw
function checkDraw() {
  for (let index in board) {
    if (!board[index]) {
      return false;
    }
  }
  return true;
}

// Function to make the AI's move
function aiMove() {
  let bestScore = -Infinity;
  let bestMove = null;
  for (let index in board) {
    if (!board[index]) {
      board[index] = 'O';
      let score = minimax(0, false);
      board[index] = null;
      if (score > bestScore) {
        bestScore = score;
        bestMove = index;
      }
    }
  }
  board[bestMove] = 'O';
}

// Function to make the human's move
function humanMove(index) {
  board[index] = 'X';
}

// Function to play the game
function playGame() {
  let currentTurn = 'X';
  while (true) {
    if (currentTurn === 'X') {
      printBoard();
      let index = parseInt(prompt('Enter your move (0-8):'));
      humanMove(index);
      if (checkWinner() === 'X') {
        printBoard();
        console.log('You win!');
        return;
      } else if (checkDraw()) {
        printBoard();
        console.log('It\'s a draw!');
        return;
      }
    } else {
