      if (checkWinner() === 'O') {
        printBoard();
        console.log('AI wins!');
        return;
      } else if (checkDraw()) {
        printBoard();
        console.log('It\'s a draw!');
        return;
      }
    }
    currentTurn = currentTurn === 'X' ? 'O' : 'X';
  }
}

// Function to calculate the score of a node using the minimax algorithm
function minimax(depth, isMaximizing) {
  let result = checkWinner();
  if (result) {
    return isMaximizing ? -result : result;
  }
  if (checkDraw()) {
    return 0;
  }

  let bestScore = isMaximizing ? -Infinity : Infinity;
  for (let index in board) {
    if (!board[index]) {
      board[index] = 'O';
      let score = minimax(depth + 1, !isMaximizing);
      board[index] = null;
      if (isMaximizing && score > bestScore) {
        bestScore = score;
      } else if (!isMaximizing && score < bestScore) {
        bestScore = score;
      }
    }
  }
  return bestScore;
}

// Start the game
playGame();
